def part(names, servings, std, ingredients, change, method, note, sources, matrix="solid", drippings=None, bulk=None, flat=None):
    cooking = dict(method=method, mass_change_g=change, note=note)
    if drippings:
        cooking["drippings"] = drippings
    d = dict(names=names, matrix=matrix, servings_source=servings, standard_serving_g=std, ingredients=ingredients, cooking=cooking, sources=sources)
    if bulk:
        d["bulk_density_g_ml"] = bulk
    if flat:
        d["flat_plate"] = dict(coverage=flat[0], height_cm=flat[1])
    return d


